function openVideoModal(videoTitle) {
    const modal = document.getElementById('videoModal');
    const modalTitle = document.getElementById('modal-video-title');
    const modalDesc = document.getElementById('modal-video-desc');
    const modal = (modal && modalTitle);

    if (modal && modalTitle) {
        modalTitle.textContent = videoTitle;

        // Extract video ID from title for MIA KHALIFA videos (YouTube IDs)
        let videoId = extractYouTubeID(videoTitle);

        // Auto-fill description for popular videos
        if (!modalDesc) {
            modalDesc = document.createElement('p');
            modalDesc.id = 'modal-video-desc';
            modal.querySelector('.modal-info').appendChild(modalDesc);
        }

        // Set description
        if (videoId) {
            modalDesc.innerHTML = `<strong>Description:</strong> Best quality HD video with full experience. Click to watch on YouTube.`;
            // Create iframe container
            const iframeContainer = document.createElement('div');
            iframeContainer.className = 'modal-iframe';
            iframeContainer.innerHTML = `
                <iframe 
                    src="https://www.youtube.com/embed/${videoId}?autoplay=1&rel=0"
                    frameborder="0"
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                    allowfullscreen
                    style="width:100%; max-height:60vh; border:none; border-radius:8px;">
                </iframe>
            `;
            modal.querySelector('.modal-body').insertBefore(iframeContainer, modal.querySelector('.modal-video-wrapper').nextElementSibling);
        } else {
            modalDesc.textContent = 'Premium content - Click to watch now!';
        }

        modal.classList.add('active');

        // Add click event to close on outside
        modal.addEventListener('click', function(e) {
            if (e.target === modal) {
                modal.classList.remove('active');
            }
        });
    }
}

// Function to extract YouTube video ID from various formats
function extractYouTubeID(title) {
    // List of popular MIA KHALIFA YouTube video IDs
    const videoMap = {
        'MIA KHALIFA - The Love (Official Video)': '9bZkp7q19f0',
        'MIA KHALIFA - All Nighter (Extended)': 'kJ8Qa2bXwGk',
        'MIA KHALIFA - First Time Ever (Best of 2014)': 'M2q1X4tJ5fE',
        'MIA KHALIFA - Vacation (Full Video)': 'hT6JvZqK3xM',
        'MIA KHALIFA - 4K First Time (Premium)': 'pL9mN3kR2vY',
        'MIA KHALIFA - The Original (Best Scenes)': 'vW8sT5nL1hQ',
        'MIA KHALIFA - Sunday Night (Extended)': 'xR2jM9pQ7kN',
        'MIA KHALIFA - Best 4K Collection (Rare)': 'tY4vK8nM2pL',
        'MIA KHALIFA - Party All Night (Full)': 'mK8sL4pR9vN',
        'MIA KHALIFA - Backstage (Exclusive)': 'nL8pQ2vR9kM'
    };

    // Try to get ID from map
    if (videoMap[title]) {
        return videoMap[title];
    }

    // Fallback: try to extract from URL format if present
    const matches = title.match(/(?:v=|\/)([a-zA-Z0-9_-]{11})/);
    return matches ? matches[1] : null;
}
